const mkSimitGrid = () => {
  const g = Array.from({ length: SIMIT.art.length }, () => new Array(SIMIT.cols).fill(null));
  for (const k in SFLET) { const [r, c] = k.split('-').map(Number); const e = SFLET[k]; g[r][c] = { value: e[0], color: SIMIT.colors[e[2]], clueIds: e[1] }; }
  for (const a of SFART) { g[a[0]][a[1]] = { art: true, color: SIMIT.colors[a[2]] }; }
  return g;
};
