export function getPuzzle(cityId, puzzleId) {
  const set = CITY_PUZZLES[cityId] || ISTANBUL_PUZZLES;
  return set[puzzleId] || ISTANBUL_PUZZLES[1];
}

// Bu şehrin KENDİ bulmacaları var mı? (yoksa getPuzzle İstanbul'a düşer)
export function hasPuzzles(cityId) {
  return Object.prototype.hasOwnProperty.call(CITY_PUZZLES, cityId);
}
